mapper.select:
SELECT Count(distinct(log_id)) from operation_log  where 1 = 1


        and op_content ~* #{logContent}


        and operator ~* #{userName}


        and op_time  between  to_timestamp(#{startTime},'yyyy-MM-dd hh24:mi:ss') and to_timestamp(#{endTime},'yyyy-MM-dd hh24:mi:ss')


        and req_ip ~* #{reqIP}

select log_id,
op_content,
operator,
req_ip,
op_time
from operation_log
where 1 = 1


        and operator ~* #{userName}


        and op_content ~* #{logContent}


        and req_ip ~* #{reqIP}


        and op_time  between  to_timestamp(#{startTime},'yyyy-MM-dd hh24:mi:ss') and to_timestamp(#{endTime},'yyyy-MM-dd hh24:mi:ss')






                        order by op_content ${pageInfo.sord}


                        order by op_time ${pageInfo.sord}


                        order by operator ${pageInfo.sord}



                    order by op_time desc



                LIMIT ${pageInfo.pageSize} offset (${pageInfo.pageNum} - 1) * ${pageInfo.pageSize}



            order by op_time desc

select
count(0) > 0
from map_version_info mvi
left join map_server_info msi
on mvi.server_id = msi.server_id
where
mvi.version ~ #{version}
and mvi.name = #{serviceName}
and msi.server_name = #{layer}

select protocol_name as serverName, count(protocol_name) as countNum from server_request_statistic where 1=1
req_start_time between #{startTime} and #{endTime}
group by protocol_name order by countNum ${sort}
select server_name as serverName
, visit_num as countNum
, ave_reponse_time as countNum
, max_concurrent as countNum
from server_visit_statistic order by countNum ${sort}
select server_name as serverName, max(count) as countNum from (select server_name, count(to_char(req_start_time,'YYYY-MM-DD hh:MI:SS')) as count from server_request_statistic where to_char(req_start_time,'YYYY-MM-DD hh:MI:SS') = to_char(req_end_time,'YYYY-MM-DD hh:MI:SS') and req_start_time between #{startTime} and #{endTime} group by server_name,to_char(req_start_time,'YYYY-MM-DD hh:MI:SS') ) t group by server_name order by countNum ${sort}
select server_name as serverName
, count(id) as countNum
, round(avg(reponse_time)) as countNum
from server_request_statistic where req_start_time between #{startTime} and #{endTime} group by server_name,server_type order by countNum ${sort}
limit 5

