mapper.select:
select count(distinct(sl.log_id)) from system_log sl
where 1 = 1


        and sl.sys_log_user ~* #{userName}


        and sl.sys_log_content ~* #{logContent}


        and sl.sys_log_level = #{logLevel}


        and sl.sys_log_time  between  to_timestamp(#{startTime},'yyyy-MM-dd hh24:mi:ss') and to_timestamp(#{endTime},'yyyy-MM-dd hh24:mi:ss')


        and sys_log_src_ip = #{reqIP}

select log_id,
sys_log_level,
sys_log_content,
sys_log_src,
sys_log_user,
sys_log_src_ip,
sys_log_time
from system_log
where 1 = 1


        and sys_log_src_ip ~* #{reqIP}


        and sys_log_level = #{logLevel}


        and sys_log_user ~* #{userName}


        and sys_log_content ~* #{logContent}


        and sys_log_time  between to_timestamp(#{startTime},'yyyy-MM-dd hh24:mi:ss') and to_timestamp(#{endTime},'yyyy-MM-dd hh24:mi:ss')






                        order by sys_log_content ${pageInfo.sord}


                        order by sys_log_time ${pageInfo.sord}


                        order by sys_log_user ${pageInfo.sord}



                    order by sys_log_time desc



                LIMIT ${pageInfo.pageSize} offset (${pageInfo.pageNum} - 1) * ${pageInfo.pageSize}



            order by sys_log_time desc

mapper.update:
update server_request_statistic
set server_name = #{newServerName}
where server_id = #{serverId}

update server_visit_statistic
set server_name = #{newServerName}
where server_id = #{serverId}

mapper.select:
select id, server_type, server_name, protocol_name, reponse_time, req_start_time, req_end_time, req_ip, server_id from server_request_statistic where
req_start_time > #{saveEndTime}
req_start_time between #{saveLastEndTime} and #{saveEndTime}
